import { render, screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { MemoryRouter } from 'react-router'
import { describe, expect, it } from 'vitest'
import App from '../App'
import { installFakeApi } from './fakeApi'

function renderAt(path: string) {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <App />
    </MemoryRouter>,
  )
}

describe('App routes', () => {
  it('shows the issue list at /', async () => {
    installFakeApi()
    renderAt('/')
    expect(screen.getByRole('heading', { level: 1, name: 'Issue Tracker' })).toBeInTheDocument()
    expect(await screen.findByText('Showing 4 of 4 issues')).toBeInTheDocument()
  })

  it('has a navigation bar with an Issues link that is marked as the current page on /', async () => {
    installFakeApi()
    renderAt('/')
    const nav = screen.getByRole('navigation')
    const link = within(nav).getByRole('link', { name: 'Issues' })
    expect(link).toHaveAttribute('href', '/')
    expect(link).toHaveAttribute('aria-current', 'page')
    await screen.findByText('Showing 4 of 4 issues')
  })

  it('keeps the navigation bar on every page, but not marked current away from /', async () => {
    installFakeApi()
    renderAt('/edit/000000000000000000000001')
    const link = within(screen.getByRole('navigation')).getByRole('link', { name: 'Issues' })
    expect(link).not.toHaveAttribute('aria-current')
    await screen.findByLabelText('Title')
  })

  it('shows a Page not found screen for an address nobody handles, with the navigation bar still there', () => {
    installFakeApi()
    renderAt('/nope')
    expect(screen.getByRole('heading', { name: 'Page not found' })).toBeInTheDocument()
    expect(screen.getByRole('navigation')).toBeInTheDocument()
    expect(screen.getByRole('link', { name: 'Back to the issue list' })).toHaveAttribute('href', '/')
  })

  it('does not use /issues for a screen, because /issues belongs to the API', () => {
    installFakeApi()
    renderAt('/issues/000000000000000000000001')
    expect(screen.getByRole('heading', { name: 'Page not found' })).toBeInTheDocument()
  })

  it('goes to the edit screen for an issue when View is clicked', async () => {
    installFakeApi()
    renderAt('/')
    await screen.findByText('Showing 4 of 4 issues')
    const card = screen.getByRole('heading', { name: 'Typo on the home page' }).closest('article') as HTMLElement
    await userEvent.click(within(card).getByRole('button', { name: 'View' }))
    expect(await screen.findByRole('heading', { name: 'Edit issue' })).toBeInTheDocument()
    expect(await screen.findByLabelText('Title')).toHaveValue('Typo on the home page')
  })
})

describe('Edit screen', () => {
  it('works when it is the very first thing loaded, like a refresh (reads the id from the address)', async () => {
    const { seen } = installFakeApi()
    renderAt('/edit/000000000000000000000003')
    expect(screen.getByRole('status')).toHaveTextContent(/loading/i)
    expect(await screen.findByLabelText('Title')).toHaveValue('Search is slow on big lists')
    expect(screen.getByLabelText('Description')).toHaveValue('Description 3')
    expect(screen.getByLabelText('Steps to reproduce')).toHaveValue('Steps 3')
    expect(screen.getByLabelText('Priority')).toHaveValue('medium')
    expect(seen[0]).toMatchObject({ method: 'GET', url: '/issues/000000000000000000000003' })
  })

  it('shows the server message and a way back when the issue does not exist', async () => {
    installFakeApi()
    renderAt('/edit/000000000000000000000999')
    expect(await screen.findByRole('alert')).toHaveTextContent('Issue not found')
    expect(screen.getByRole('link', { name: 'Back to all issues' })).toHaveAttribute('href', '/')
    expect(screen.queryByLabelText('Title')).not.toBeInTheDocument()
  })

  it('saves with PATCH /issues/:id, then returns to the list showing the change', async () => {
    const { seen } = installFakeApi()
    renderAt('/edit/000000000000000000000002')
    const title = await screen.findByLabelText('Title')
    await userEvent.clear(title)
    await userEvent.type(title, 'Typo on the about page')
    await userEvent.selectOptions(screen.getByLabelText('Priority'), 'high')
    await userEvent.click(screen.getByRole('button', { name: 'Save changes' }))

    expect(await screen.findByText('Showing 4 of 4 issues')).toBeInTheDocument()
    expect(screen.getByRole('heading', { name: 'Typo on the about page' })).toBeInTheDocument()
    const patch = seen.find((r) => r.method === 'PATCH')
    expect(patch?.url).toBe('/issues/000000000000000000000002')
    expect(patch?.body).toEqual({
      title: 'Typo on the about page',
      description: 'Description 2',
      stepsToReproduce: 'Steps 2',
      priority: 'high',
    })
  })

  it('stays on the edit screen and shows the message when the API refuses the save', async () => {
    installFakeApi(undefined, { failures: { 'PATCH /issues/000000000000000000000002': 403 } })
    renderAt('/edit/000000000000000000000002')
    await screen.findByLabelText('Title')
    await userEvent.type(screen.getByLabelText('Title'), ' again')
    await userEvent.click(screen.getByRole('button', { name: 'Save changes' }))
    expect(await screen.findByText('Your role may not do that')).toBeInTheDocument()
    expect(screen.getByRole('heading', { name: 'Edit issue' })).toBeInTheDocument()
  })

  it('has a link back to the list', async () => {
    installFakeApi()
    renderAt('/edit/000000000000000000000001')
    await screen.findByLabelText('Title')
    await userEvent.click(screen.getByRole('link', { name: 'Back to all issues' }))
    expect(await screen.findByText('Showing 4 of 4 issues')).toBeInTheDocument()
  })
})
